function dtGini(counts,total){ var g=0; for(var c in counts){ var p=counts[c]/total; g+=p*(1-p); } return g; }
function dtBestSplit(data,feat){ var vals=data.map(function(d){return d.x[feat];}), uniq=Array.from(new Set(vals)).sort(function(a,b){return a-b;}), best=null;
  for(var i=0;i<uniq.length-1;i++){ var th=(uniq[i]+uniq[i+1])/2, l={},r={},tl=0,tr=0;
    data.forEach(function(d){ var c=d.y; if(d.x[feat]<=th){ l[c]=(l[c]||0)+1; tl++; } else { r[c]=(r[c]||0)+1; tr++; } });
    if(tl===0||tr===0) continue; var g=tl/data.length*dtGini(l,tl)+tr/data.length*dtGini(r,tr); if(!best||g<best.g) best={th:th,g:g}; }
  return best; }
function dtTrain(data,feats,depth,maxDepth){ var cnt={}; data.forEach(function(d){ cnt[d.y]=(cnt[d.y]||0)+1; }); var maj=null,mv=-1;
  for(var c in cnt) if(cnt[c]>mv){mv=cnt[c];maj=+c;}
  if(depth>=maxDepth || data.length<=1) return {leaf:true,cls:maj};
  var bf=null,bs=null,bg=Infinity; feats.forEach(function(f){ var s=dtBestSplit(data,f); if(s&&s.g<bg){bg=s.g;bf=f;bs=s;} });
  if(!bs || bg>=dtGini(cnt,data.length)) return {leaf:true,cls:maj};
  if(!bs || bg>=dtGini(cnt,data.length)) return {leaf:true,cls:maj};
  var ld=[],rd=[]; data.forEach(function(d){ if(d.x[bf]<=bs.th) ld.push(d); else rd.push(d); });
  return {leaf:false,feat:bf,th:bs.th,left:dtTrain(ld,feats,depth+1,maxDepth),right:dtTrain(rd,feats,depth+1,maxDepth),cls:maj}; }
function dtPredict(tree,x){ if(tree.leaf) return tree.cls; return x[tree.feat]<=tree.th ? dtPredict(tree.left,x) : dtPredict(tree.right,x); }
var EXPORTS={dtGini:dtGini, dtBestSplit:dtBestSplit, dtTrain:dtTrain, dtPredict:dtPredict};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.DecisionTreeForgePure = EXPORTS; }
